function node(name, children = []) {
    const result = { name, children, parent: null };
    for (const child of children) {
        child.parent = result;
    }
    return result;
}

function closest(start, name) {
    for (let current = start; current; current = current.parent) {
        if (current.name === name) return current;
    }
    return null;
}

const button = node("button");
const card = node("div", [node("h3"), button]);
const body = node("body", [card]);
console.log(closest(button, "div") === card);
console.log(closest(button, "button") === button);
console.log(closest(button, "body") === body);
console.log(closest(button, "table"));

function parseSelector(selector) {
    const match = selector.match(/^([a-z][a-z0-9]*)?(?:#([\w-]+))?((?:\.[\w-]+)*)$/i);
    if (!match) return null;
    const [, tag, id, classes] = match;
    return {
        tag: tag ?? null,
        id: id ?? null,
        classes: classes ? classes.slice(1).split(".") : [],
    };
}

console.log(parseSelector("div"));
console.log(parseSelector("#menu"));
console.log(parseSelector("li.item.hot"));
console.log(parseSelector("ul > li"));

