function el(name, id, children = []) {
    const result = { name, id, children, parent: null };
    for (const child of children) {
        child.parent = result;
    }
    return result;
}

function pathOf(node) {
    const parts = [];
    for (let current = node; current; current = current.parent) {
        let part = current.name;
        if (current.id) {
            part += "#" + current.id;
        } else if (current.parent) {
            part += ":nth-child(" + (current.parent.children.indexOf(current) + 1) + ")";
        }
        parts.unshift(part);
    }
    return parts.join(" > ");
}

