function matchesAttr(attrs, selector) {
    const m = selector.match(/^\[([\w-]+)(?:([\^$*]?)=["']?([^"'\]]*)["']?)?\]$/);
    if (!m) throw new Error("Selektor tushunarsiz: " + selector);
    const [, name, op, expected] = m;
    if (!(name in attrs)) return false;
    if (expected === undefined) return true;
    const actual = String(attrs[name]);
    if (op === "^") return actual.startsWith(expected);
    if (op === "$") return actual.endsWith(expected);
    if (op === "*") return actual.includes(expected);
    return actual === expected;
}

