function parseAttributes(tag) {
    const rest = tag.replace(/^<\w+\s*/, "").replace(/\s*\/?>$/, "");
    const attrs = {};
    for (const m of rest.matchAll(/([\w-]+)(?:="([^"]*)")?/g)) {
        attrs[m[1]] = m[2] ?? "";
    }
    return attrs;
}

console.log(parseAttributes('<input type="email" name="user" required>'));
console.log(parseAttributes('<a href="/about" data-id="5" target="_blank">'));

function attrsToString(attrs) {
    const escape = (v) => String(v).replace(/&/g, "&amp;").replace(/"/g, "&quot;");
    return Object.entries(attrs)
        .filter(([, value]) => value !== false && value != null)
        .map(([name, value]) => (value === true ? name : `${name}="${escape(value)}"`))
        .join(" ");
}

console.log(attrsToString({ type: "text", required: true, disabled: false }));
console.log(attrsToString({ title: 'Ali "Vali"', "data-id": 5, hidden: true }));
console.log(attrsToString({ class: "btn", id: null }));

