function render(template, data) {
    const escape = (v) => String(v).replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[ch]);
    return template.replace(/\{\{\s*(\w+)\s*\}\}/g, (_, key) => escape(data[key] ?? ""));
}

