class TreeNode {
    constructor(name) {
        this.name = name;
        this.parent = null;
        this.children = [];
    }

    append(child) {
        child.remove();
        child.parent = this;
        this.children.push(child);
        return this;
    }

    remove() {
        if (!this.parent) return;
        this.parent.children = this.parent.children.filter((c) => c !== this);
        this.parent = null;
    }
}

