function parseStyle(text) {
    const result = {};
    for (const part of text.split(";")) {
        const index = part.indexOf(":");
        if (index === -1) continue;
        const name = part.slice(0, index).trim();
        const value = part.slice(index + 1).trim();
        const camel = name.replace(/-([a-z])/g, (_, ch) => ch.toUpperCase());
        result[camel] = value;
    }
    return result;
}

