function toCss(styles) {
    return Object.entries(styles)
        .map(([key, value]) => {
            const name = key.replace(/[A-Z]/g, (ch) => "-" + ch.toLowerCase());
            const unitless = key === "opacity" || key === "zIndex";
            const text = typeof value === "number" && !unitless && value !== 0 ? value + "px" : value;
            return `${name}: ${text}`;
        })
        .join("; ");
}

