function diffClasses(oldText, newText) {
    const oldSet = new Set(oldText.split(/\s+/).filter(Boolean));
    const newSet = new Set(newText.split(/\s+/).filter(Boolean));
    return {
        add: [...newSet].filter((name) => !oldSet.has(name)),
        remove: [...oldSet].filter((name) => !newSet.has(name))
    };
}

