function classNames(...parts) {
    const result = [];
    for (const part of parts) {
        if (!part) continue;
        if (typeof part === "string") {
            result.push(part);
        } else {
            for (const [name, enabled] of Object.entries(part)) {
                if (enabled) result.push(name);
            }
        }
    }
    return result.join(" ");
}

