class MiniClassList {
    constructor(text = "") {
        this.names = new Set(text.split(/\s+/).filter(Boolean));
    }

    add(...list) {
        list.forEach((name) => this.names.add(name));
    }

    remove(...list) {
        list.forEach((name) => this.names.delete(name));
    }

    toggle(name, force) {
        const need = force === undefined ? !this.names.has(name) : force;
        need ? this.names.add(name) : this.names.delete(name);
        return need;
    }

    get value() {
        return [...this.names].join(" ");
    }
}

