function fit(image, box, mode) {
    const scaleX = box.width / image.width;
    const scaleY = box.height / image.height;
    const scale = mode === "contain" ? Math.min(scaleX, scaleY) : Math.max(scaleX, scaleY);
    return { width: image.width * scale, height: image.height * scale };
}

const image = { width: 800, height: 400 };
const box = { width: 400, height: 400 };
console.log(JSON.stringify(fit(image, box, "contain")));
console.log(JSON.stringify(fit(image, box, "cover")));

function makeRect(left, top, width, height) {
    return {
        left, top, width, height,
        right: left + width,
        bottom: top + height,
        centerX: left + width / 2,
        centerY: top + height / 2
    };
}

const rect = makeRect(50, 30, 100, 60);
console.log(JSON.stringify(rect));
console.log(rect.right - rect.left === rect.width);

function boxSizes({ width, padding, border, boxSizing }) {
    const extra = 2 * padding + 2 * border;
    const offset = boxSizing === "border-box" ? width : width + extra;
    return { offsetWidth: offset, clientWidth: offset - 2 * border };
}

console.log(JSON.stringify(boxSizes({ width: 200, padding: 10, border: 5, boxSizing: "content-box" })));
console.log(JSON.stringify(boxSizes({ width: 200, padding: 10, border: 5, boxSizing: "border-box" })));

function clientToPage(point, scroll) {
    return { x: point.x + scroll.x, y: point.y + scroll.y };
}

function pageToClient(point, scroll) {
    return { x: point.x - scroll.x, y: point.y - scroll.y };
}

const click = { x: 120, y: 80 };
const scroll = { x: 0, y: 600 };
const page = clientToPage(click, scroll);
console.log(JSON.stringify(page));
console.log(JSON.stringify(pageToClient(page, scroll)));

function isNearBottom({ scrollTop, clientHeight, scrollHeight }, threshold = 100) {
    return scrollHeight - (scrollTop + clientHeight) <= threshold;
}

console.log(isNearBottom({ scrollTop: 0, clientHeight: 700, scrollHeight: 3000 }));
console.log(isNearBottom({ scrollTop: 2150, clientHeight: 700, scrollHeight: 3000 }));
console.log(isNearBottom({ scrollTop: 2300, clientHeight: 700, scrollHeight: 3000 }));
console.log(isNearBottom({ scrollTop: 2300, clientHeight: 700, scrollHeight: 3000 }, 0));

function clamp(value, min, max) {
    return Math.min(Math.max(value, min), max);
}

function scrollProgress(scrollTop, clientHeight, scrollHeight) {
    const max = scrollHeight - clientHeight;
    if (max <= 0) return 0;
    return Math.round((clamp(scrollTop, 0, max) / max) * 100);
}

console.log(scrollProgress(0, 700, 3000));
console.log(scrollProgress(1150, 700, 3000));
console.log(scrollProgress(2300, 700, 3000));
console.log(scrollProgress(9999, 700, 3000));
console.log(scrollProgress(0, 700, 500));

function visibleRatio(rect, viewport) {
    const width = Math.min(rect.right, viewport.width) - Math.max(rect.left, 0);
    const height = Math.min(rect.bottom, viewport.height) - Math.max(rect.top, 0);
    if (width <= 0 || height <= 0) return 0;
    return (width * height) / ((rect.right - rect.left) * (rect.bottom - rect.top));
}

const viewport = { width: 1000, height: 700 };
console.log(visibleRatio({ left: 100, top: 100, right: 300, bottom: 200 }, viewport));
console.log(visibleRatio({ left: 100, top: 650, right: 300, bottom: 750 }, viewport));
console.log(visibleRatio({ left: 100, top: 800, right: 300, bottom: 900 }, viewport));

function placeTooltip(target, tip, viewport) {
    let top = target.bottom + 8;
    if (top + tip.height > viewport.height) top = target.top - tip.height - 8;
    let left = target.left + target.width / 2 - tip.width / 2;
    left = Math.max(0, Math.min(left, viewport.width - tip.width));
    return { left, top };
}

const viewport = { width: 1000, height: 600 };
const tip = { width: 120, height: 40 };
console.log(JSON.stringify(placeTooltip({ left: 440, top: 100, bottom: 130, width: 80 }, tip, viewport)));
console.log(JSON.stringify(placeTooltip({ left: 440, top: 540, bottom: 570, width: 80 }, tip, viewport)));
console.log(JSON.stringify(placeTooltip({ left: 10, top: 100, bottom: 130, width: 40 }, tip, viewport)));

function easeInOut(t) {
    return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2;
}

function smoothSteps(from, to, steps) {
    const result = [];
    for (let i = 0; i <= steps; i++) {
        result.push(Math.round(from + (to - from) * easeInOut(i / steps)));
    }
    return result;
}

console.log(smoothSteps(0, 800, 8).join(" "));
console.log(smoothSteps(500, 0, 4).join(" "));

function contains(rect, point) {
    return point.x >= rect.left && point.x <= rect.right
        && point.y >= rect.top && point.y <= rect.bottom;
}

function distance(a, b) {
    return Math.hypot(a.x - b.x, a.y - b.y);
}

const rect = { left: 50, top: 30, right: 150, bottom: 90 };
