function isValidEmail(value) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value.trim());
}

for (const value of ["aziz@mail.uz", "aziz@mail", "@mail.uz", "a b@mail.uz", " nilufar@gmail.com "]) {
    console.log(JSON.stringify(value), isValidEmail(value));
}

function passwordScore(password) {
    let score = 0;
    if (password.length >= 8) score++;
    if (/[a-z]/.test(password) && /[A-Z]/.test(password)) score++;
    if (/\d/.test(password)) score++;
    if (/[^A-Za-z0-9]/.test(password)) score++;
    return score;
}

for (const password of ["abc", "abcdefgh", "Abcdefgh1", "Abcdefg1!"]) {
    console.log(password.padEnd(10), passwordScore(password));
}

function formatPhone(input) {
    let digits = input.replace(/\D/g, "");
    if (digits.length === 9) digits = "998" + digits;
    if (digits.length !== 12 || !digits.startsWith("998")) return null;
    const [, code, a, b, c] = /^998(\d{2})(\d{3})(\d{2})(\d{2})$/.exec(digits);
    return `+998 ${code} ${a} ${b} ${c}`;
}

