console.log(formatPhone("+998 (90) 123 45 67"));
console.log(formatPhone("998901234567"));
console.log(formatPhone("12345"));

const rules = {
    name: [(v) => v.trim() !== "" || "Ism kiritilmagan"],
    age: [
        (v) => v !== "" || "Yosh kiritilmagan",
        (v) => Number(v) >= 18 || "Yosh kamida 18 bo'lishi kerak"
    ]
};

function validate(data) {
    const errors = {};
    for (const [field, checks] of Object.entries(rules)) {
        for (const check of checks) {
            const result = check(data[field] ?? "");
            if (result !== true) {
                errors[field] = result;
                break;
            }
        }
    }
    return errors;
}

console.log(JSON.stringify(validate({ name: "Aziz", age: "21" })));
console.log(JSON.stringify(validate({ name: " ", age: "16" })));
console.log(JSON.stringify(validate({ name: "Zilola" })));

function nest(entries) {
    const result = {};
    for (const [key, value] of entries) {
        const path = key.split(/[\[\]]+/).filter(Boolean);
        let target = result;
        path.forEach((part, index) => {
            if (index === path.length - 1) target[part] = value;
            else target = target[part] ??= {};
        });
    }
    return result;
}

