console.log(JSON.stringify(nest(data)));

function normalizeName(value) {
    return value
        .trim()
        .replace(/\s+/g, " ")
        .split(" ")
        .map((word) => word[0].toUpperCase() + word.slice(1).toLowerCase())
        .join(" ");
}

